import 'dart:convert';

final catalogueVocabulary =
    jsonDecode(
          r'''{"MeasurementFamilies":["MASS","VOLUME","COUNT","LOCAL_CONTAINER","PACKAGE","GROUPED_COUNT","LOAD","VARIABLE_WEIGHT","VARIABLE_COUNT","PRICE_PORTION","OTHER_CONTROLLED"],"MeasurementModes":["FIXED","VARIABLE_WEIGHT","VARIABLE_COUNT","LOCAL_CONTAINER","PACKAGE_COUNT","PRICE_PORTION"],"CalibrationSources":["VENDOR_MEASURED","MANUFACTURER_DECLARED","PACKAGE_DECLARED","PLATFORM_VERIFIED","OTHER_CONTROLLED"],"IdentifierTypes":["INTERNAL_SKU","GTIN","EAN","UPC","BARCODE","MANUFACTURER_CODE","OTHER_CONTROLLED"],"FreshAttributeOptions":{"RIPENESS":["GREEN","TURNING","RIPE","VERY_RIPE"],"QUALITY_GRADE":["STANDARD","SELECTED","PREMIUM","PROCESSING_GRADE"],"SIZE_GRADE":["SMALL","MEDIUM","LARGE"],"COLOUR":["RED","GREEN","YELLOW","WHITE","DARK","MIXED"],"FIRMNESS":["SOFT","FIRM","VERY_FIRM"],"CUT":["WHOLE","CUT","SLICED","DICED","CHOPPED","PORTIONED"],"CLEANING":["CLEANED","UNCLEANED","WASHED","UNWASHED"],"PEELING":["PEELED","UNPEELED"],"TRIMMING":["TRIMMED","UNTRIMMED"],"GUTTING":["GUTTED","UNGUTTED"],"DESCALING":["DESCALED","NOT_DESCALED"],"HEAD":["HEAD_ON","HEAD_OFF"],"BONE":["BONE_IN","BONELESS"],"PRESERVATION":["FRESH","FROZEN","SMOKED","DRIED"],"SELECTION":["SELECTED","UNSELECTED"],"PACKAGING_PREFERENCE":["BAGGED","WRAPPED","BOXED","NONE"]},"classAttributes":{"FRESH_PRODUCE":["RIPENESS","QUALITY_GRADE","SIZE_GRADE","COLOUR","FIRMNESS","CUT","CLEANING","PEELING","TRIMMING","SELECTION","PACKAGING_PREFERENCE"],"MEAT":["QUALITY_GRADE","SIZE_GRADE","CUT","CLEANING","BONE","PRESERVATION","SELECTION","PACKAGING_PREFERENCE"],"FISH":["QUALITY_GRADE","SIZE_GRADE","CUT","CLEANING","GUTTING","DESCALING","HEAD","PRESERVATION","SELECTION","PACKAGING_PREFERENCE"],"FROZEN":["QUALITY_GRADE","SIZE_GRADE","CUT","PRESERVATION","PACKAGING_PREFERENCE"],"CHILLED":["QUALITY_GRADE","SIZE_GRADE","CUT","PRESERVATION","PACKAGING_PREFERENCE"],"DRY_BULK":["QUALITY_GRADE","SIZE_GRADE","CLEANING","SELECTION","PACKAGING_PREFERENCE"],"LOCAL_FOODSTUFF":["QUALITY_GRADE","SIZE_GRADE","CLEANING","SELECTION","PACKAGING_PREFERENCE"],"DAIRY":["QUALITY_GRADE","PACKAGING_PREFERENCE"],"BEVERAGE":["QUALITY_GRADE","PACKAGING_PREFERENCE"],"PACKAGED":["QUALITY_GRADE","PACKAGING_PREFERENCE"],"BAKED_PACKAGED":["QUALITY_GRADE","PACKAGING_PREFERENCE"],"HOUSEHOLD_GROCERY":["QUALITY_GRADE","PACKAGING_PREFERENCE"],"OTHER":["QUALITY_GRADE","PACKAGING_PREFERENCE"]}}''',
        )
        as Map<String, dynamic>;
List<String> catalogueVocabularyList(String name) =>
    (catalogueVocabulary[name] as List).cast<String>();
Map<String, List<String>> catalogueVocabularyMap(String name) =>
    (catalogueVocabulary[name] as Map).map(
      (key, value) => MapEntry(key.toString(), (value as List).cast<String>()),
    );
